START TRANSACTION;
ALTER TABLE "ItensVenda" ALTER COLUMN "ProdutoId" DROP NOT NULL;

ALTER TABLE "ItensVenda" ADD "BazarProdutoId" integer;

ALTER TABLE "ItensVenda" ADD "TipoItem" character varying(10) NOT NULL DEFAULT 'normal';

CREATE TABLE "BazarConsignantes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EmpresaId" integer NOT NULL,
    "Nome" character varying(120) NOT NULL,
    "Telefone" character varying(20) NOT NULL,
    "Cpf" character varying(14),
    "Observacao" text,
    "Ativo" boolean NOT NULL DEFAULT TRUE,
    "CriadoEm" timestamp with time zone NOT NULL,
    "AtualizadoEm" timestamp with time zone NOT NULL,
    "DeletadoEm" timestamp with time zone,
    CONSTRAINT "PK_BazarConsignantes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_BazarConsignantes_Empresas_EmpresaId" FOREIGN KEY ("EmpresaId") REFERENCES "Empresas" ("Id") ON DELETE CASCADE
);

CREATE TABLE "BazarRepasses" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EmpresaId" integer NOT NULL,
    "ConsignanteId" integer NOT NULL,
    "ValorTotal" numeric(10,2) NOT NULL,
    "DataGeracao" timestamp with time zone NOT NULL,
    "DataPagamento" timestamp with time zone,
    "Status" character varying(20) NOT NULL DEFAULT 'Pendente',
    "FormaPagamento" character varying(30),
    "Observacao" text,
    "CriadoPor" integer NOT NULL,
    "PagoPor" integer,
    "CriadoEm" timestamp with time zone NOT NULL,
    "AtualizadoEm" timestamp with time zone NOT NULL,
    "DeletadoEm" timestamp with time zone,
    CONSTRAINT "PK_BazarRepasses" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_BazarRepasses_BazarConsignantes_ConsignanteId" FOREIGN KEY ("ConsignanteId") REFERENCES "BazarConsignantes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_BazarRepasses_Empresas_EmpresaId" FOREIGN KEY ("EmpresaId") REFERENCES "Empresas" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_BazarRepasses_Usuarios_CriadoPor" FOREIGN KEY ("CriadoPor") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_BazarRepasses_Usuarios_PagoPor" FOREIGN KEY ("PagoPor") REFERENCES "Usuarios" ("Id") ON DELETE SET NULL
);

CREATE TABLE "BazarSacolas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EmpresaId" integer NOT NULL,
    "ConsignanteId" integer NOT NULL,
    "DataCadastro" date NOT NULL,
    "Observacao" text,
    "CriadoEm" timestamp with time zone NOT NULL,
    "AtualizadoEm" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_BazarSacolas" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_BazarSacolas_BazarConsignantes_ConsignanteId" FOREIGN KEY ("ConsignanteId") REFERENCES "BazarConsignantes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_BazarSacolas_Empresas_EmpresaId" FOREIGN KEY ("EmpresaId") REFERENCES "Empresas" ("Id") ON DELETE CASCADE
);

CREATE TABLE "BazarProdutos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EmpresaId" integer NOT NULL,
    "ConsignanteId" integer NOT NULL,
    "SacolaId" integer NOT NULL,
    "Descricao" character varying(200) NOT NULL,
    "Tamanho" character varying(10),
    "Cor" character varying(40),
    "ValorCompra" numeric(10,2) NOT NULL,
    "ValorVenda" numeric(10,2) NOT NULL,
    "CodigoEtiqueta" character varying(50),
    "Status" character varying(20) NOT NULL DEFAULT 'Disponivel',
    "DataEntrada" date NOT NULL,
    "DataVenda" date,
    "DataDevolucao" date,
    "VendaId" integer,
    "CriadoEm" timestamp with time zone NOT NULL,
    "AtualizadoEm" timestamp with time zone NOT NULL,
    "DeletadoEm" timestamp with time zone,
    CONSTRAINT "PK_BazarProdutos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_BazarProdutos_BazarConsignantes_ConsignanteId" FOREIGN KEY ("ConsignanteId") REFERENCES "BazarConsignantes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_BazarProdutos_BazarSacolas_SacolaId" FOREIGN KEY ("SacolaId") REFERENCES "BazarSacolas" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_BazarProdutos_Empresas_EmpresaId" FOREIGN KEY ("EmpresaId") REFERENCES "Empresas" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_BazarProdutos_Vendas_VendaId" FOREIGN KEY ("VendaId") REFERENCES "Vendas" ("Id") ON DELETE SET NULL
);

CREATE TABLE "BazarProdutoFotos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProdutoId" integer NOT NULL,
    "Ordem" integer NOT NULL,
    "Url" character varying(500) NOT NULL,
    "CriadoEm" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_BazarProdutoFotos" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_BazarProdutoFotos_Ordem" CHECK ("Ordem" >= 0 AND "Ordem" <= 2),
    CONSTRAINT "FK_BazarProdutoFotos_BazarProdutos_ProdutoId" FOREIGN KEY ("ProdutoId") REFERENCES "BazarProdutos" ("Id") ON DELETE CASCADE
);

CREATE TABLE "BazarRepasseItens" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RepasseId" integer NOT NULL,
    "ProdutoId" integer NOT NULL,
    "Valor" numeric(10,2) NOT NULL,
    CONSTRAINT "PK_BazarRepasseItens" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_BazarRepasseItens_BazarProdutos_ProdutoId" FOREIGN KEY ("ProdutoId") REFERENCES "BazarProdutos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_BazarRepasseItens_BazarRepasses_RepasseId" FOREIGN KEY ("RepasseId") REFERENCES "BazarRepasses" ("Id") ON DELETE CASCADE
);

